// Resuelve SKU -> price, y decide si alcanza el stock.
// El SKU se guarda en el campo `sku` del price del producto en GHL.
const pedido = $('Webhook · apartar').first().json.body;
const sku = (pedido.sku || '').trim();
const cantidad = Number(pedido.cantidad || 1);

const productos = $input.first().json.products || [];
let encontrado = null;

for (const p of productos) {
  for (const precio of (p.prices || [])) {
    if ((precio.sku || '').trim() === sku) {
      encontrado = { productId: p._id || p.id, priceId: precio._id || precio.id,
                     nombre: p.name, monto: Number(precio.amount ?? 0),
                     disponible: Number(precio.availableQuantity ?? 0) };
    }
  }
}

if (!encontrado) {
  return [{ json: { ok: false, motivo: 'sku_no_existe', sku, cantidad } }];
}

const alcanza = encontrado.disponible >= cantidad;
return [{ json: { ...encontrado, sku, cantidad, alcanza,
                  nuevoStock: encontrado.disponible - cantidad,
                  ok: alcanza, motivo: alcanza ? null : 'agotado' } }];

// El reloj del apartado. expira_en va en ISO 8601 CON OFFSET, siempre.
// N2 lo compara contra la hora actual y SP02 tiene que escribirlo igual.
const datos = $('Resolver SKU y stock').first().json;
const contactId = $('Webhook · apartar').first().json.body.contactId;
const horas = Number($env.HORAS_APARTADO || 24);
const expira = new Date(Date.now() + horas * 3600 * 1000);

return [{ json: {
  ok: true,
  sku: datos.sku,
  articulo: datos.nombre,
  cantidad: datos.cantidad,
  productId: datos.productId,
  priceId: datos.priceId,
  monto: datos.monto,
  contactId,
  stockRestante: datos.nuevoStock,
  expira_en: expira.toISOString()
} }];

