// Junta el apartado con la factura. La liga es la que el agente manda por WhatsApp.
// /invoices/ NO devuelve la liga; se arma a mano. Formato confirmado el 25 sep.
const apartado = $('Arrancar reloj de 24 h').first().json;
const factura = $('GHL · crear factura').first().json;
const invoice_id = factura._id || factura.id;
return [{ json: { ...apartado, invoice_id,
  liga_pago: `${$env.GHL_INVOICE_URL_BASE}/invoice/${invoice_id}` } }];
